-- --- users (ADR-0004, PDPA) ----------------------------------------------------------------
ALTER TABLE users
  ADD CONSTRAINT ck_users__phone_e164 CHECK (phone IS NULL OR phone ~ '^\+[1-9][0-9]{7,14}$'),
  ADD CONSTRAINT ck_users__customer_passwordless CHECK (kind <> 'customer' OR password_hash IS NULL),
  ADD CONSTRAINT ck_users__failed_login_count CHECK (failed_login_count >= 0);

ALTER TABLE auth_sessions
  ADD CONSTRAINT ck_auth_sessions__expiry CHECK (expires_at > issued_at AND idle_expires_at > issued_at),
  ADD CONSTRAINT ck_auth_sessions__octets CHECK (octet_length(refresh_token_hash) = 32),
  ADD CONSTRAINT ck_auth_sessions__revoked CHECK ((revoked_at IS NULL) = (revoke_reason IS NULL));

ALTER TABLE otp_challenges
  ADD CONSTRAINT ck_otp_challenges__phone_e164 CHECK (phone ~ '^\+[1-9][0-9]{7,14}$'),
  ADD CONSTRAINT ck_otp_challenges__attempts CHECK (attempts >= 0 AND max_attempts > 0 AND attempts <= max_attempts),
  ADD CONSTRAINT ck_otp_challenges__octets CHECK (octet_length(code_hash) = 32);

ALTER TABLE device_pins ADD CONSTRAINT ck_device_pins__failed_attempts CHECK (failed_attempts >= 0);
ALTER TABLE password_reset_tokens ADD CONSTRAINT ck_password_reset_tokens__octets CHECK (octet_length(token_hash) = 32);

-- --- roles, permissions, grants (D-140) ----------------------------------------------------
ALTER TABLE roles ADD CONSTRAINT ck_roles__key CHECK (key ~ '^[a-z][a-z0-9_]*$');
ALTER TABLE permissions ADD CONSTRAINT ck_permissions__key CHECK (key ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$');

ALTER TABLE user_roles
  ADD CONSTRAINT ck_user_roles__scope CHECK ((scope_type = 'platform') = (scope_id IS NULL)),
  ADD CONSTRAINT ck_user_roles__window CHECK (valid_to IS NULL OR valid_to > valid_from),
  ADD CONSTRAINT ck_user_roles__reason CHECK (btrim(reason) <> '');
CREATE UNIQUE INDEX ux_user_roles__active
  ON user_roles (user_id, role_id, scope_type, COALESCE(scope_id, 0)) WHERE revoked_at IS NULL;

-- A grant must match the role's scope type and the user's audience (ADR-0004: audiences never mix).
CREATE FUNCTION user_roles_match_role() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  role_scope role_scope_type;
  role_audience token_audience;
  user_kind_value user_kind;
BEGIN
  SELECT scope_type, audience INTO role_scope, role_audience FROM roles WHERE id = NEW.role_id;
  SELECT kind INTO user_kind_value FROM users WHERE id = NEW.user_id;
  IF NEW.scope_type <> role_scope THEN
    RAISE EXCEPTION 'role scope is %, grant scope is %', role_scope, NEW.scope_type USING ERRCODE = 'check_violation';
  END IF;
  IF user_kind_value::text <> role_audience::text THEN
    RAISE EXCEPTION 'a % user cannot hold a % role', user_kind_value, role_audience USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER tg_user_roles__match_role BEFORE INSERT OR UPDATE OF user_id, role_id, scope_type ON user_roles
  FOR EACH ROW EXECUTE FUNCTION user_roles_match_role();

-- --- SoD rules (accounting-design.md §8) ---------------------------------------------------
ALTER TABLE sod_rules
  ADD CONSTRAINT ck_sod_rules__key CHECK (key ~ '^[a-z][a-z0-9_]*$'),
  ADD CONSTRAINT ck_sod_rules__shape CHECK (
    (kind = 'role_pair' AND role_a_id IS NOT NULL AND role_b_id IS NOT NULL AND role_a_id <> role_b_id
       AND action_a IS NULL AND action_b IS NULL) OR
    (kind = 'action_pair' AND action_a IS NOT NULL AND action_b IS NOT NULL
       AND role_a_id IS NULL AND role_b_id IS NULL AND subject_match IS NOT NULL));

-- --- consent (D-005, D-144) ----------------------------------------------------------------
ALTER TABLE consent_purposes ADD CONSTRAINT ck_consent_purposes__key CHECK (key ~ '^[a-z][a-z0-9_]*$');

ALTER TABLE consent_purpose_versions
  ADD CONSTRAINT ck_consent_purpose_versions__version_no CHECK (version_no > 0),
  ADD CONSTRAINT ck_consent_purpose_versions__reason CHECK (btrim(reason) <> ''),
  ADD CONSTRAINT ck_consent_purpose_versions__decided CHECK (status NOT IN ('approved', 'rejected') OR decided_at IS NOT NULL);
CREATE TRIGGER tg_consent_purpose_versions__immutable BEFORE UPDATE OR DELETE ON consent_purpose_versions
  FOR EACH ROW EXECUTE FUNCTION forbid_decided_version_change();

ALTER TABLE consent_records ADD CONSTRAINT ck_consent_records__subject
  CHECK (user_id IS NOT NULL OR anonymous_id IS NOT NULL);

-- The denormalised purpose_id must be the purpose of purpose_version_id.
CREATE FUNCTION consent_records_match_purpose() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM consent_purpose_versions WHERE id = NEW.purpose_version_id AND purpose_id = NEW.purpose_id) THEN
    RAISE EXCEPTION 'purpose_id does not match purpose_version_id' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER tg_consent_records__match_purpose BEFORE INSERT ON consent_records
  FOR EACH ROW EXECUTE FUNCTION consent_records_match_purpose();
CREATE TRIGGER tg_consent_records__append_only BEFORE UPDATE OR DELETE ON consent_records
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();
